const req = $('Webhook').first().json.body ?? {};
const phone = String(req.phone ?? '').replace(/\D/g, '').slice(-10);
const res = $json ?? {};

// Cratio does not always answer at the top level. An IP-allowlist rejection
// arrives as {"data":"\n{\"error\":\"You are not allowed...\"}"} — the real
// reply is a JSON STRING nested inside `data`. Unwrap before deciding, or a
// hard refusal reads as "no such lead".
let body = res;
if (typeof res?.data === 'string') {
  try { body = JSON.parse(res.data.trim()); } catch { body = { error: res.data.trim() }; }
}

// THREE outcomes, not two. A bad key, a wrong formname, an unknown field or a
// blocked IP all make Cratio return an error — and if that reads as "not
// found", a misconfigured lookup is indistinguishable from a lead that
// genuinely went missing, and the dashboard raises a critical alert about the
// wrong system entirely.
const err = body?.error ?? body?.Error ?? (Array.isArray(body) ? body[0]?.error : null);
if (err) {
  return [{ json: { result: 'LEAD_ERROR', checked: phone, detail: String(err).slice(0, 200) } }];
}

// {"success":[{"totalrows":N,"data":[...]}]} on a hit.
const rows = Number(body?.success?.[0]?.totalrows ?? 0);
const found = rows > 0 || (phone.length === 10 && JSON.stringify(body).includes(phone));

// A token, never the phone number itself: a not-found reply that echoed the
// value back would match the search string and read as a hit.
return [{ json: {
  result: found ? 'LEAD_FOUND' : 'LEAD_MISSING',
  checked: phone,
  rows,
  // Enough of the raw reply to diagnose the next problem without another run.
  detail: found ? undefined : JSON.stringify(body).slice(0, 200),
} }];
